package com.fakelegacy.catalog;

import java.math.BigDecimal;
import java.math.RoundingMode;

public final class PriceUtils {

    private PriceUtils() {
    }

    public static BigDecimal round2(BigDecimal v) {
        return v.setScale(2, RoundingMode.HALF_UP);
    }

    public static BigDecimal tierRate(String tier) {
        if ("GOLD".equals(tier)) {
            return new BigDecimal("0.10");
        }
        if ("SILVER".equals(tier)) {
            return new BigDecimal("0.05");
        }
        return BigDecimal.ZERO;
    }

    /** Same rounding as the order lines: the discount amount is rounded, then subtracted. */
    public static BigDecimal applyTier(BigDecimal price, String tier) {
        return round2(price).subtract(round2(price.multiply(tierRate(tier))));
    }
}
